import { BlockTypes, ItemStack, TicksPerSecond } from "@minecraft/server";
import { PassiveRoutine } from "BigBrain/Routines/PassiveRoutine";
import V3 from "Helpers/Vectors/V3";
import VirtualInventoryComponent from "Inventory/VirtualInventoryComponent";
import AsyncUtils from "Utils/AsyncUtils";
import TestUtil from "Test/TestUtil";
import AbstractPassiveTest from "./AbstractPassiveTest";
class SmeltFoodAtHomeTest extends AbstractPassiveTest {
    async run(test) {
        // AIP in one corner
        const aip = this.spawnAIP(test, new V3(1, 2, 1), {
            root: PassiveRoutine
        });
        // Home Marker
        const bedTestLocation = new V3(13, 2, 13);
        TestUtil.createHome(test, bedTestLocation);
        // Two chests beside the home marker with materials split between them
        const chest1Location = new V3(12, 2, 13);
        test.setBlockType(BlockTypes.get("minecraft:chest"), chest1Location);
        this.setupChest1(test.getBlock(chest1Location));
        const chest2Location = new V3(10, 2, 13);
        test.setBlockType(BlockTypes.get("minecraft:chest"), chest2Location);
        this.setupChest2(test.getBlock(chest2Location));
        // A nearby furnace starts with cooked chicken already in the output slot
        const furnaceLocation = new V3(11, 2, 13);
        test.setBlockType(BlockTypes.get("minecraft:furnace"), furnaceLocation);
        this.setupFurnace(test.getBlock(furnaceLocation));
        await test.idle(1);
        this.setupAIPInventory(aip);
        await AsyncUtils.waitForCondition(()=>{
            const inv = VirtualInventoryComponent.get(aip);
            return inv.hasItemType("minecraft:cooked_chicken") && !inv.hasItemType("minecraft:chicken");
        });
        test.assert(VirtualInventoryComponent.get(aip).hasItemType("minecraft:cooked_chicken"), "AIP missing cooked chicken");
        test.assert(!VirtualInventoryComponent.get(aip).hasItemType("minecraft:chicken"), "AIP should not have raw chicken");
        test.succeed();
    }
    setupAIPInventory(aip) {
        // Give AIP wooden tools (inferior gear — should be deposited after crafting)
        const inv = VirtualInventoryComponent.get(aip);
        inv.giveItem(new ItemStack("minecraft:wooden_pickaxe"));
        inv.giveItem(new ItemStack("minecraft:wooden_axe"));
        inv.giveItem(new ItemStack("minecraft:wooden_shovel"));
        inv.giveItem(new ItemStack("minecraft:wooden_sword"));
        inv.giveItem(new ItemStack("minecraft:chicken", 64));
    }
    setupFurnace(furnace) {
        const container = furnace.getComponent("minecraft:inventory")?.container;
        if (!container) return;
        container.setItem(2, new ItemStack("minecraft:cooked_chicken", 64));
    }
    setupChest1(chest) {
        const container = InventoryUtil.getContainer(chest);
        if (!container) return;
        // Raw materials for stone age crafting
        container.addItem(new ItemStack("minecraft:cobblestone", 16));
        // Supplies
        container.addItem(new ItemStack("minecraft:torch", 64));
        container.addItem(new ItemStack("minecraft:coal", 64));
    }
    setupChest2(chest) {
        const container = InventoryUtil.getContainer(chest);
        if (!container) return;
        // More raw materials for stone age crafting
        container.addItem(new ItemStack("minecraft:oak_log", 64));
        // Supplies
        container.addItem(new ItemStack("minecraft:cooked_beef", 8));
    }
    constructor(...args){
        super(...args);
        this.identifier = "smelt_food_at_home";
        this.structure = "bedrock_box";
        this.maxTicks = 5 * 60 * TicksPerSecond;
    }
}
export { SmeltFoodAtHomeTest as default };

